import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"魔法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills-magic.md","filePath":"guide/skills-magic.md","lastUpdated":1786201985000}'),n={name:"guide/skills-magic.md"};function r(i,t,o,l,p,h){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="魔法" tabindex="-1">魔法 <a class="header-anchor" href="#魔法" aria-label="Permalink to &quot;魔法&quot;">​</a></h1><p>释放魔法会消耗<strong>魔法值</strong>。魔法通常来源于角色装备的<strong>魔法卡包</strong>，但部分角色也可能初始就自带魔法。</p><blockquote><p>魔法卡包是魔法技能的主要来源，其标准实现见 <a href="/guide/prefabricated-entities.html">预制实体 - 魔法卡包</a>。</p></blockquote><h2 id="魔法流程" tabindex="-1">魔法流程 <a class="header-anchor" href="#魔法流程" aria-label="Permalink to &quot;魔法流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>行动回合 → 选择魔法 → 选择目标 → 开始吟唱 → 结束回合</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>回合外 → 吟唱结束 → 发动效果</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>回合外 → 硬直时间衰减 → 下次行动回合</span></span></code></pre></div><h2 id="等级" tabindex="-1">等级 <a class="header-anchor" href="#等级" aria-label="Permalink to &quot;等级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>初始</th><th>最高</th><th>升级方式</th></tr></thead><tbody><tr><td>角色自带</td><td>1 级</td><td>8 级</td><td>等级解锁 (8/16/24/32/40/48/56)</td></tr><tr><td>魔法卡包</td><td>卡包决定</td><td>—</td><td>魔法卡升级（没有等级要求）</td></tr></tbody></table><hr><h2 id="魔法瓶颈" tabindex="-1">魔法瓶颈 <a class="header-anchor" href="#魔法瓶颈" aria-label="Permalink to &quot;魔法瓶颈&quot;">​</a></h2><p>部分魔法技能可能对角色的<strong>智力</strong>具有要求，我们称之为<strong>魔法瓶颈</strong>。</p><h2 id="魔法效能" tabindex="-1">魔法效能 <a class="header-anchor" href="#魔法效能" aria-label="Permalink to &quot;魔法效能&quot;">​</a></h2><p><code>魔法效能</code> 是一个表示魔法技能<strong>实际施展效果被放大或缩小</strong>的系数关系：以<strong>魔法瓶颈为基准线</strong>，角色智力减去魔法瓶颈的<strong>差值的正负</strong>决定了实际施展效果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>魔法效能 = 1.0 + (角色智力 - 魔法瓶颈) ÷ 魔法瓶颈</span></span></code></pre></div><table tabindex="0"><thead><tr><th>智力 vs 瓶颈</th><th>魔法效能</th><th>实际效果</th></tr></thead><tbody><tr><td>智力 = 瓶颈</td><td>100%</td><td>标准效果</td></tr><tr><td>智力 &lt; 瓶颈</td><td>&lt; 100%（最低可降至 1%）</td><td>效果被削弱</td></tr><tr><td>智力 &gt; 瓶颈</td><td>&gt; 100%（至多可提升至 200%）</td><td>效果获得增强</td></tr></tbody></table>`,14)])])}const b=a(n,[["render",r]]);export{g as __pageData,b as default};
